
'use strict';
const DATA=JSON.parse(document.getElementById('player-card-data').textContent);
const $=id=>document.getElementById(id);
const LIVE=DATA.mode==='live';
const CARD_TABS=['shooting','contract','awards'];
const enabledTabs=CARD_TABS.filter(t=>(Array.isArray(DATA.enabled_tabs)?DATA.enabled_tabs:CARD_TABS).includes(t));
const PERIODS=Array.isArray(DATA.periods)?DATA.periods:[];
const contractPayload=()=>DATA.contracts||{as_of:DATA.as_of||null,status:'unavailable',summary:'No contract ledger is supplied for this player in this record.',current:null,history:[],metrics:[],sections:[],sources:[]};
const contractHashTab=hash=>hash==='#contract'||hash==='#contract-history'?'contract':hash==='#awards'?'awards':hash==='#shooting'?'shooting':null;
const known=n=>n!==null&&n!==undefined&&n!==''&&Number.isFinite(Number(n));
const count=n=>known(n)?String(n):'N/A';
const rate=(n,d)=>known(n)&&known(d)&&Number(d)>0?Number(n)/Number(d):null;
const safeHref=value=>typeof value==='string'&&value.trim()&&!/^(?:[a-z][a-z0-9+.-]*:|\/\/)/i.test(value.trim())?value:typeof value==='string'&&/^https?:\/\//i.test(value)?value:null;
const legacyLinks={stats:'player_stats_preview.md',shooting:'sample_shooting.md',contract:'sample_contract.md',awards:'sample_awards.md',definitions:'../player_statistics.md',milestones:'player_milestones/career_milestones_preview.html'};
const recordLink=key=>safeHref(DATA.links?.[key]??(LIVE?null:legacyLinks[key]));
const competitionName=(p={})=>p.competition_label||({regular:'Regular season',regular_season:'Regular season',summer:'Summer League',summer_league:'Summer League',preseason:'Preseason',playoffs:'Playoffs',play_in:'Play-In',nba_cup:'NBA Cup',national_team:'National team',national_qualifiers:'National qualifiers',national_finals:'National tournament',national_friendlies:'National friendlies'}[p.competition]||p.competition||(!LIVE?'Regular season':''));
const periodLabel=p=>{if(!LIVE)return [competitionName(p),p.label].filter(Boolean).join(' · ');const competition=competitionName(p),parts=String(p.label||'').split(' · ').filter(x=>x&&x!==competition&&x!==p.season);if(p.cutoff&&!parts.join(' ').includes(p.cutoff))parts.push('through '+p.cutoff);return [competition,p.season,...parts].filter(Boolean).join(' · ');};
const appearances=p=>p.appearances===undefined?p.shooting.games:p.appearances;
const geometrySupported=()=>period().geometry_supported!==false;
const fgPoints=b=>known(b.fgm)&&known(b.tpm)?2*Number(b.fgm)+Number(b.tpm):null;
const sourceAnchor=(href,label)=>safeHref(href)?`<a href="${esc(safeHref(href))}">${esc(label)}</a>`:esc(label);
function initializeLinks(){[['header-stats-link','stats'],['footer-stats-link','stats'],['footer-shooting-link','shooting'],['footer-awards-link','awards'],['footer-definitions-link','definitions'],['footer-milestones-link','milestones']].forEach(([id,key])=>{const link=$(id),href=recordLink(key);link.hidden=!href;if(href)link.href=href;});const contractLink=$('footer-contract-link');contractLink.hidden=!enabledTabs.includes('contract');contractLink.href=recordLink('contract')||'#contract';if(enabledTabs.length===1&&enabledTabs[0]==='contract'){const directory=recordLink('contracts')||recordLink('contract_directory');if(directory){$('header-stats-link').hidden=false;$('header-stats-link').href=directory;$('header-stats-link').textContent='All player contract pages ↗';$('footer-stats-link').hidden=false;$('footer-stats-link').href=directory;$('footer-stats-link').textContent='All player contract pages';}}}


const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=(n,d=1)=>!known(n)?'N/A':Number(n).toFixed(d);
const percent=n=>!known(n)?'N/A':number(n*100,1)+'%';
const icons={trophy:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.4" aria-hidden="true"><path d="M7 3h10v7a5 5 0 0 1-10 0V3ZM7 5H3v3a5 5 0 0 0 5 5M17 5h4v3a5 5 0 0 1-5 5M12 15v5M7 21h10"/></svg>',star:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.2" aria-hidden="true"><path d="m12 2 3 6.3 7 .9-5 4.9 1.2 7L12 17.8l-6.2 3.3 1.2-7-5-4.9 7-.9Z"/></svg>'};
const requestedTab=contractHashTab(location.hash)||DATA.defaultTab||DATA.default_tab||'shooting';
const state={tab:enabledTabs.includes(requestedTab)?requestedTab:enabledTabs[0]||'contract',period:new URLSearchParams(location.search).get('period')||DATA.default_period||null,zone:'all',bin:null,hoverZone:null,hoverBin:null,labels:false,missing:false,awardScenario:DATA.awards?.default_scenario||'current',contractTab:location.hash==='#contract-history'?'history':'current',contractId:new URLSearchParams(location.search).get('contract')||null};
if(!PERIODS.some(p=>p.id===state.period))state.period=PERIODS.find(p=>p.id===DATA.default_period)?.id||PERIODS[0]?.id||null;
const zoneMeta=[{id:'paint',label:'Paint',description:'Inside the 16-foot lane, from the baseline through the free-throw line.',xy:[0,-7]},{id:'under_12',label:'Outside paint · under 12 ft',short:'Under 12 ft',description:'Outside the paint and less than 12 feet from the center of the basket.',xy:[-11,0]},{id:'12_to_18',label:'12 to under 18 ft',short:'12–18 ft',description:'Non-paint, two-point attempts at least 12 feet and less than 18 feet from the basket.',xy:[-14,-11]},{id:'18_to_3pt',label:'18 ft to the three-point line',short:'18 ft to line',description:'Two-point attempts at least 18 feet from the basket, up to and including the three-point line.',xy:[0,-20]},{id:'three',label:'Three-point range',short:'Three-point',description:'Beyond the 23 ft 9 in arc or the 22-foot corner line. Shots on the line are two-pointers.',xy:[0,-29]}];
const period=()=>PERIODS.find(p=>p.id===state.period)||null;
const zoneName=id=>zoneMeta.find(z=>z.id===id)?.label||id;
const tracking=()=>state.missing?{status:'unavailable',located_attempts:0,recorded_attempts:0}:period().shooting.coverage;
const complete=()=>!state.missing&&geometrySupported()&&period().shooting.coverage.status==='complete';
const gameCount=()=>period().shooting.games;
function announce(msg){$('announcement').textContent=msg;}
function initializeIdentity(){const p=period(),award=state.tab==='awards'?awardsScenario():null,i={...DATA.identity,...(state.tab==='contract'?(contractPayload().identity||{}):(award?.identity||p?.identity||{}))},name=i.name||'Player';$('player-name').textContent=name;$('player-initials').textContent=i.initials||name.split(/\s+/).map(x=>x[0]).join('').slice(0,2);$('player-number').textContent=i.jersey==null?'':String(i.jersey).padStart(2,'0');$('identity-sub').innerHTML=[i.team,i.position,i.age!=null?'Age '+i.age:null,i.jersey!=null?'#'+i.jersey:null].filter(Boolean).map(s=>`<span>${esc(s)}</span>`).join('<span class="dot" aria-hidden="true"></span>');$('identity-eyebrow').textContent=LIVE?'Player career record':'Illustrative player profile';$('identity-status').textContent=LIVE?(i.status||i.contract_status||'Career record'):'Fictional example';document.title=name+' · '+(state.tab==='contract'?'Contract':state.tab==='awards'?'Awards':'Shooting');$('footer-caption').textContent=[name,state.tab==='contract'?'Contract record':state.tab==='awards'?'Annual awards':competitionName(p||{}),state.tab==='contract'?'Full terms, dated evidence and source records':'Source-linked aggregation, fixed visual scales'].filter(Boolean).join(' · ');const photo=i.photo_url||i.photo_path||'',portrait=$('portrait');if(portrait.dataset.photo!==photo){portrait.dataset.photo=photo;portrait.querySelector('img')?.remove();let note=portrait.querySelector('.portrait-note');if(!note){note=document.createElement('span');note.className='portrait-note';portrait.append(note);}note.textContent='No photo supplied';if(photo&&(/^(https?:\/\/|data:image\/|\.\.?\/)/.test(photo))){const img=new Image();img.alt=name+' portrait';img.onload=()=>{if(portrait.dataset.photo===photo){portrait.querySelector('.portrait-note')?.remove();portrait.append(img);}};img.onerror=()=>{if(portrait.dataset.photo===photo)note.textContent='Photo unavailable';};img.src=photo;}}}
function setControls(){const current=period(),kinds=[...new Set(PERIODS.map(p=>p.kind))];$('scope-select').innerHTML=kinds.map(k=>`<option value="${esc(k)}" ${k===current?.kind?'selected':''}>${esc(k[0].toUpperCase()+k.slice(1))}</option>`).join('');$('period-select').innerHTML=PERIODS.filter(p=>p.kind===current?.kind).map(p=>`<option value="${esc(p.id)}" ${p.id===state.period?'selected':''}>${esc(periodLabel(p))}</option>`).join('');$('period-controls').hidden=state.tab!=='shooting'||!current;const award=state.tab==='awards'?awardsScenario():null,cutoff=state.tab==='contract'?contractPayload().as_of:award?award.cutoff:current?.cutoff;$('identity-cutoff').textContent=cutoff?'Through '+cutoff:'Cutoff not recorded';if(state.tab==='contract'){$('record-notice').textContent=contractPayload().notice||(LIVE?'CONTRACT RECORD · Dated agreements, control records and evidence. Missing terms remain unrecorded; proposals and cap holds are not signed salary.':'ILLUSTRATIVE CONTRACT VIEW · Any supplied contract record is a design example, separate from live career results.');return;}if(LIVE){$('record-notice').textContent=DATA.notice||'Career record · Closed game results and confirmed awards through the selected cutoff.';}else{$('identity-status').textContent=award&&award.id!=='current'?'Independent award scenario':'Fictional example';$('record-notice').textContent=award&&award.id!=='current'?'INDEPENDENT AWARD DESIGN SCENARIO · Fictional earned-year layout only. Separate from the six-game 2003 sample, Wade’s career and any future award outcome.':'FICTIONAL EXAMPLE · Same six sample appearances as the statistical reports. Shot locations demonstrate the interface; they are not recorded Wade shots or live career results.';}}
function render(){initializeIdentity();setControls();document.querySelectorAll('[data-tab]').forEach(b=>{const enabled=enabledTabs.includes(b.dataset.tab),selected=enabled&&b.dataset.tab===state.tab;b.hidden=!enabled;b.setAttribute('aria-selected',String(selected));b.tabIndex=selected?0:-1;});$('player-view').setAttribute('aria-labelledby','tab-'+state.tab);$('player-view').innerHTML=state.tab==='contract'?contractView():state.tab==='shooting'?shootingView():awardsView();if(state.tab==='contract')bindContracts();else if(state.tab==='shooting'){bindChart();renderInspector();}else bindAwards();}
function summaryMetric(label,value,note){return `<div class="summary-item"><div class="metric-label">${label}</div><div class="metric-value">${value}</div><div class="metric-note">${note}</div></div>`;}
function shootingView(){const p=period(),b=p.box||{},g=appearances(p),fgpts=fgPoints(b),coverage=tracking(),hasGames=known(g)&&g>0;return `<div class="view-head"><div><h2 id="view-title" tabindex="-1">Shooting profile</h2><p>${esc(periodLabel(p))}${LIVE?'':' · '+esc(p.season)} · ${hasGames?count(g)+' appearance'+(g===1?'':'s'):g===0?'No appearances':'Appearances unknown'}<br>Hover, focus or tap the court to inspect a zone or a shot cluster.</p></div><span class="pill ${coverage.status!=='complete'?'red':''}">${!geometrySupported()?'Court geometry unavailable':g===0?'No appearances':coverage.status==='complete'?'<span class="status-dot"></span> '+(LIVE?'Complete recorded tracking':'Complete sample tracking'):coverage.status==='partial'?'Partial tracking':'Tracking unavailable'}</span></div>
<div class="summary">${summaryMetric('Field-goal percentage',percent(rate(b.fgm,b.fga)),known(b.fgm)&&known(b.fga)?b.fgm+' makes / '+b.fga+' attempts':'Field-goal totals unavailable')}${summaryMetric('Field-goal points / game',number(rate(fgpts,g)),'From made 2s and 3s only')}${summaryMetric('Attempts / game',number(rate(b.fga,g)),hasGames?'All makes and misses included':g===0?'No appearance denominator':'Appearance denominator unavailable')}${summaryMetric('Three-point percentage',percent(rate(b.tpm,b.tpa)),count(b.tpm)+' / '+count(b.tpa)+' from three')}${summaryMetric('Total points / game',number(rate(b.pts,g)),'Includes free throws')}</div>
<div class="shooting-layout"><section class="panel chart-panel" aria-labelledby="court-title"><div class="chart-top"><div><h3 id="court-title">Where the attempts come from</h3><p>${geometrySupported()?'NBA half court · basket at the bottom':'Competition court geometry is unverified'}</p></div><div class="chart-actions"><button class="micro-button" id="all-attempts" aria-pressed="${state.zone==='all'&&!state.bin}">All attempts</button><button class="micro-button" ${geometrySupported()?'':'disabled'} id="zone-labels" aria-pressed="${state.labels}">Zone labels</button></div></div><div class="court-wrap" ${geometrySupported()?'':'style="aspect-ratio:54 / 51;width:100%"'}>${geometrySupported()?courtSVG():''}${!complete()||!hasGames?blankChart():''}</div><div class="chart-annotation"><span>HEXAGON AREA = ATTEMPTS / GAME</span><span>BLUE = LOWER FG% · RED = HIGHER FG%</span></div><div class="legend"><div class="legend-block"><span class="legend-title">Field-goal percentage</span><div class="color-scale" role="img" aria-label="Fixed color scale: zero percent blue, fifty percent cream, one hundred percent red"></div><div class="legend-labels"><span>0%</span><span>25%</span><span>50%</span><span>75%</span><span>100%</span></div><p class="legend-footnote">Absolute accuracy, not a comparison with league average.</p></div><div class="legend-block"><span class="legend-title">Attempts per game in each hex</span><div class="size-scale">${[[.25,5],[1,10],[4,20]].map(([n,size])=>`<span class="size-item"><i class="size-dot" style="width:${size}px;height:${size}px"></i>${n}</span>`).join('')}</div><p class="legend-footnote">Area grows with frequency. Same scale in every period.<br>Dashed outline = fewer than 5 attempts in the selected period.</p></div></div></section>
<aside class="detail-column" aria-label="Shot selection details"><section class="panel"><div class="panel-pad" id="spot-detail"></div><div class="zone-controls" role="group" aria-label="Select a shooting zone"><button class="zone-button" data-zone="all" aria-pressed="${state.zone==='all'&&!state.bin}">All locations</button>${zoneMeta.map(z=>`<button class="zone-button" data-zone="${z.id}" aria-pressed="${state.zone===z.id&&!state.bin}">${esc(z.short||z.label)}</button>`).join('')}</div></section><section class="panel panel-pad"><h3 class="support-title">Attempt distribution</h3><div class="mini-bars">${zoneMeta.map(z=>{const row=p.shooting.zones.find(r=>r.id===z.id),attempts=complete()?row?.fga:null,share=complete()?rate(attempts,b.fga):null;return `<div><div class="mini-bar-label"><span>${esc(z.short||z.label)}</span><b>${share===null?'Unavailable':percent(share)}</b></div><div class="mini-bar"><span style="width:${share===null?0:share*100}%"></span></div></div>`;}).join('')}</div><p class="insight">Zones do not overlap. Paint takes priority over distance bands; three-point geometry takes priority over two-point distance.</p></section></aside></div>
<section class="panel data-table-panel" aria-labelledby="zone-table-title"><div class="panel-head"><div><h3 id="zone-table-title">The numbers behind the court</h3><p>Field-goal points exclude free throws. Per-game rates use every appearance in this period.</p></div>${LIVE?'':`<label class="tracking-switch"><input id="tracking-unavailable" type="checkbox" ${state.missing?'checked':''}> Preview missing tracking</label>`}</div><div class="table-scroll"><table id="zone-table"><thead><tr><th scope="col">Shooting zone</th><th scope="col" class="num">FGM / FGA</th><th scope="col" class="num">FG%</th><th scope="col" class="num">FG points / game</th><th scope="col" class="num">FGA / game</th><th scope="col">Sample</th></tr></thead><tbody>${zoneMeta.map(z=>zoneTableRow(z)).join('')}</tbody></table></div><div class="source-note">${sourceNote()}<details ${LIVE?'open':''} style="margin-top:8px"><summary style="cursor:pointer;color:#a1a8b5">Inspect source games and definitions</summary><ul style="margin-top:9px;padding-left:20px">${sourceGames()}</ul><p style="margin-top:8px">FG% = makes ÷ attempts. Field-goal points/game = (2-point makes × 2 + 3-point makes × 3) ÷ appearances. Attempt frequency = zone or hex attempts ÷ appearances. A DNP is excluded from the appearance denominator. Missing coordinates are never inferred from a box score.</p></details></div></section>`;}
function sourceNote(){const p=period(),c=tracking(),g=appearances(p);if(state.missing)return 'MISSING-TRACKING PREVIEW · Box-score totals remain available; every location statistic is unavailable. This control changes only the displayed coverage state.';if(LIVE){const supplied=p.source_note||p.sourceNote||'';let detail;if(!geometrySupported())detail='Court geometry is unavailable for this competition. No locations are mapped onto an unverified court.';else if(g===0)detail='No recorded appearances in this period. Shooting percentages and per-game rates have no appearance denominator.';else if(c.status!=='complete')detail=`INCOMPLETE COVERAGE · ${count(c.located_attempts)} located attempts observed; ${count(c.missing_attempts)} missing, ${count(c.unlocated_attempts)} unlocated and ${count(c.outside_view_attempts)} outside-view attempts. Zone rates and frequency sizes are unavailable.`;else detail=`RECORDED LOCATION DATA · ${count(c.located_attempts)} located attempts; ${count(p.box?.fga)} field-goal attempts in the same source games. ${count(g)} appearances. Source game, box-score and shot records are linked below where available.`;return esc([supplied,detail].filter(Boolean).join(' '));}if(c.status!=='complete')return `INCOMPLETE COVERAGE · ${c.located_attempts??0} located attempts observed; ${c.missing_attempts==null?'unknown':c.missing_attempts} missing, ${c.unlocated_attempts??0} unlocated and ${c.outside_view_attempts??0} outside-view attempts. Zone rates and frequency sizes are withheld, not shown as zero.`;return `ILLUSTRATIVE LOCATION DATA · ${c.located_attempts??0} located attempts reconcile to ${p.box.fga??0} field-goal attempts in the same fictional report games. Locations and bin groupings are interface examples, not recorded career tracking. ${p.appearances??p.shooting.games} appearances; source games linked below.`;}
function sourceGames(){const p=period();if(!p.source_games?.length)return '<li>'+(appearances(p)===0?'No closed game source records in this period.':'No linked game source records are available for this period.')+'</li>';return p.source_games.map(g=>{const label=[g.date,g.opponent].filter(Boolean).join(' · ')||g.id||'Game record',refs=[sourceAnchor(g.href,label)];if(g.appearance)refs.push(esc(g.appearance));if(g.result_href||g.box_href)refs.push(sourceAnchor(g.result_href||g.box_href,'Recorded box score'));if(g.shot_href||g.shot_source_href)refs.push(sourceAnchor(g.shot_href||g.shot_source_href,'Recorded shot data'));return '<li>'+refs.join(' · ')+'</li>';}).join('');}
function zoneTableRow(z){const r=period().shooting.zones.find(x=>x.id===z.id),ok=complete(),fgm=ok?r?.fgm:null,fga=ok?r?.fga:null,observed=!state.missing&&geometrySupported()&&known(r?.observed_fgm)&&known(r?.observed_fga);return `<tr data-row-zone="${z.id}" class="${state.zone===z.id?'active':''}"><th scope="row"><button class="text-button" data-zone="${z.id}" style="color:inherit;text-decoration:none;padding:0;text-align:left">${esc(z.label)}</button></th><td class="num">${ok?`${count(fgm)} / ${count(fga)}`:observed?`${count(r.observed_fgm)} / ${count(r.observed_fga)} observed`:'N/A'}</td><td class="num percent">${ok?percent(r?.fg_pct):'N/A'}</td><td class="num">${ok?number(r?.fg_ppg):'N/A'}</td><td class="num">${ok?number(r?.fga_per_game):'N/A'}</td><td>${!ok?'Unavailable':!known(fga)?'Unknown':fga===0?'No attempts':fga<5?'Low sample':'Descriptive sample'}</td></tr>`;}
function blankChart(){const p=period(),g=appearances(p),noGames=g===0,unknown=!known(g),partial=!state.missing&&tracking().status==='partial',unsupported=!geometrySupported();return `<div class="blank-chart"><div class="blank-message"><h3>${unsupported?'Court geometry unavailable':noGames?'No appearance in this period':unknown?'Appearance record unavailable':partial?'Some shot locations are missing':'Shot locations unavailable'}</h3><p>${unsupported?'This competition has no verified court adapter. Recorded box scores remain available; no NBA court or location breakdown is substituted.':noGames?'There is no appearance denominator or shooting sample. A recorded DNP is not a zero-percent shooting game.':unknown?'Missing appearance or box-score coverage is unknown, not a record of zero games. Only verified data is shown.':partial?'Located counts alone cannot represent the full period. Per-game zone rates and frequency-sized dots are withheld until coverage is complete.':'Box scores can still be reported. Paint, distance and shot-frequency patterns require actual location data; nothing is estimated onto the court.'}</p></div></div>`;}
function colorFor(p){if(p==null)return '#747c8b';const stops=[[0,[40,125,196]],[.25,[124,172,205]],[.5,[237,229,207]],[.75,[219,116,126]],[1,[196,33,64]]];const v=Math.max(0,Math.min(1,p));let a=stops[0],b=stops[1];for(let i=1;i<stops.length;i++){if(v<=stops[i][0]){a=stops[i-1];b=stops[i];break;}}const t=(v-a[0])/(b[0]-a[0]);return 'rgb('+a[1].map((n,i)=>Math.round(n+(b[1][i]-n)*t)).join(',')+')';}
const cornerJoin=Math.sqrt(23.75*23.75-22*22);
const twoPath=`M -22 5.25 L -22 ${-cornerJoin} A 23.75 23.75 0 0 1 22 ${-cornerJoin} L 22 5.25 Z`;
const courtPath='M -25 -41.75 H 25 V 5.25 H -25 Z';
