function hexPoints(x,y,r){return Array.from({length:6},(_,i)=>{const angle=Math.PI/3*i+Math.PI/6;return (x+r*Math.cos(angle)).toFixed(4)+','+(-y+r*Math.sin(angle)).toFixed(4);}).join(' ');}
function courtSVG(){const p=period(),s=p.shooting;const target=(id,shape)=>`<g role="button" tabindex="0" data-court-zone="${id}" aria-label="${esc(zoneName(id))}. Inspect shooting statistics." class="zone-target ${state.zone===id?'active':''}">${shape}</g>`;return `<svg class="court" id="shot-court" viewBox="-27 -43.3 54 51" role="group" aria-labelledby="court-svg-title court-svg-desc"><title id="court-svg-title">${esc(p.label)} shooting map</title><desc id="court-svg-desc">Interactive NBA half court. Blue means lower field-goal percentage and red means higher. Hexagon area represents attempts per game on a fixed scale. Select paint, distance zones or individual hexagons for exact counts and rates. An accessible table follows.</desc><defs><clipPath id="court-clip"><rect x="-25" y="-41.75" width="50" height="47"/></clipPath><clipPath id="two-clip"><path d="${twoPath}"/></clipPath><mask id="outside-paint"><rect x="-27" y="-44" width="54" height="52" fill="white"/><rect x="-8" y="-13.75" width="16" height="19" fill="black"/></mask></defs>
<g clip-path="url(#court-clip)">${target('three',`<path d="${courtPath} ${twoPath}" fill-rule="evenodd"/>`)}${target('18_to_3pt',`<path d="${twoPath} ${circlePath(18)}" fill-rule="evenodd" clip-path="url(#two-clip)"/>`)}${target('12_to_18',`<path d="${circlePath(18)} ${circlePath(12)}" fill-rule="evenodd" mask="url(#outside-paint)" clip-path="url(#two-clip)"/>`)}${target('under_12','<circle r="12" mask="url(#outside-paint)" clip-path="url(#two-clip)"/>')}${target('paint','<rect x="-8" y="-13.75" width="16" height="19"/>')}
<g pointer-events="none"><rect class="court-line" x="-25" y="-41.75" width="50" height="47"/><circle class="court-line dim" cx="0" cy="-41.75" r="6"/><circle class="court-line dim" cx="0" cy="-41.75" r="2"/><path class="court-line" d="M -22 5.25 V ${-cornerJoin} A 23.75 23.75 0 0 1 22 ${-cornerJoin} V 5.25"/><rect class="court-line" x="-8" y="-13.75" width="16" height="19"/><circle class="court-line dim" cx="0" cy="-13.75" r="6" stroke-dasharray=".25 .25"/><path class="court-line" d="M -6 -13.75 A 6 6 0 0 1 6 -13.75"/><path class="court-line dim" d="M -4 0 A 4 4 0 0 1 4 0"/><path class="court-line" d="M -3 1.25 H 3"/><circle class="court-line" r=".75"/><path class="court-line dim" d="M -8 1.75 H -9 M 8 1.75 H 9 M -8 -1.25 H -9 M 8 -1.25 H 9 M -8 -4.25 H -9 M 8 -4.25 H 9 M -8 -7.25 H -9 M 8 -7.25 H 9"/><text class="court-label" x="0" y="-33.5" text-anchor="middle">HALF COURT</text><text class="court-label" x="0" y="7" text-anchor="middle">BASELINE</text></g>
<g id="shot-bins">${complete()?s.bins.filter(b=>b.fga_per_game>0&&Number.isFinite(b.x)&&Number.isFinite(b.y)).map(b=>`<polygon role="button" tabindex="0" class="shot-bin ${b.fga<5?'low-sample':''} ${(state.zone!=='all'&&state.zone!==b.zone)?'dimmed':''} ${state.bin===b.id?'active':''}" data-bin="${esc(b.id)}" data-bin-zone="${esc(b.zone)}" points="${hexPoints(b.x,b.y,.72*Math.sqrt(b.fga_per_game))}" fill="${colorFor(b.fg_pct)}" aria-label="${esc(zoneName(b.zone))}, cluster ${esc(b.id)}: ${b.fgm} makes in ${b.fga} attempts, ${percent(b.fg_pct)}, ${number(b.fg_ppg)} field-goal points per game, ${number(b.fga_per_game)} attempts per game"><title>${esc(zoneName(b.zone))}: ${b.fgm}/${b.fga} · ${percent(b.fg_pct)} · ${number(b.fga_per_game)} FGA/game</title></polygon>`).join(''):''}</g>
<g id="court-zone-labels" ${state.labels?'':'hidden'} pointer-events="none">${zoneMeta.map(z=>{const row=s.zones.find(x=>x.id===z.id);return `<text class="zone-label" x="${z.xy[0]}" y="${z.xy[1]}" text-anchor="middle" stroke="#101318" stroke-width=".25" paint-order="stroke">${complete()?percent(row?.fg_pct):'—'}<tspan x="${z.xy[0]}" dy="1.1" font-size=".55">${esc(z.short||z.label)}</tspan></text>`;}).join('')}</g></g></svg>`;}
function detailSelection(){const p=period(),id=state.hoverBin||(state.hoverZone?null:state.bin),zone=state.hoverZone||state.zone;if(id&&complete()){const bin=p.shooting.bins.find(b=>b.id===id);if(bin)return {...bin,kind:'bin',title:zoneName(bin.zone),description:`Representative location: ${number(Math.abs(bin.x))} ft ${bin.x<0?'left of':bin.x>0?'right of':'from'} the basket axis, ${number(bin.y)} ft toward half court. Inspecting one spatial bin, not the entire zone.`};}if(zone!=='all'){const row=p.shooting.zones.find(r=>r.id===zone);return {...row,kind:'zone',title:zoneName(zone),description:zoneMeta.find(z=>z.id===zone).description};}const b=p.box||{},g=appearances(p),points=fgPoints(b),observed=key=>p.shooting.zones.every(z=>known(z[key]))?p.shooting.zones.reduce((n,z)=>n+Number(z[key]),0):null;return {kind:'all',title:'All locations',description:'All field-goal attempts in the selected period. Both makes and misses contribute to attempt frequency.',fgm:complete()?b.fgm:null,fga:complete()?b.fga:null,fg_pct:complete()?rate(b.fgm,b.fga):null,fg_points:complete()?points:null,fg_ppg:complete()?rate(points,g):null,fga_per_game:complete()?rate(b.fga,g):null,observed_fgm:observed('observed_fgm'),observed_fga:observed('observed_fga')};}
function renderInspector(){if(state.tab!=='shooting')return;const r=detailSelection(),ok=complete(),g=appearances(period()),low=ok&&r.fga>0&&r.fga<5,observed=!state.missing&&r.observed_fga!=null?`${count(r.observed_fgm)} / ${count(r.observed_fga)} located attempts observed.`:'No location breakdown can be established.';const field=(value,label,sub)=>`<div class="spot-stat"><strong>${value}</strong><span>${label}</span><small>${sub}</small></div>`;$('spot-detail').innerHTML=`<div class="spot-header"><div><div class="spot-kicker">${r.kind==='bin'?'Shot cluster':r.kind==='zone'?'Selected zone':'Period overview'}</div><h3 class="spot-title">${esc(r.title)}</h3></div><span class="pill ${low?'gold':''}">${g===0?'No appearances':!ok?'Unavailable':!known(r.fga)?'Unknown':r.fga===0?'No attempts':low?'Low sample':r.kind==='bin'?'Bin detail':'Zone detail'}</span></div><p class="spot-description">${esc(r.description)}</p><div class="spot-big"><strong style="color:${ok&&r.fg_pct!=null?colorFor(r.fg_pct):'#c2c5cc'}">${ok?percent(r.fg_pct):'—'}</strong><span>field-goal accuracy</span></div><div class="spot-stats">${field(ok?`${count(r.fgm)}/${count(r.fga)}`:'N/A','Makes / attempts','Selected period')}${field(ok?number(r.fg_points,0):'—','FG points','Excludes free throws')}${field(ok?number(r.fg_ppg):'—','FG points / game',count(g)+' appearance'+(g===1?'':'s'))}${field(ok?number(r.fga_per_game):'—','Attempts / game','Same appearance base')}</div><div class="detail-note ${low?'low':''}">${g===0?'There are no recorded appearances in this period. Per-game rates and percentages are unavailable.':!geometrySupported()?'This competition requires a verified court adapter before a location breakdown can be displayed.':!ok?`Tracking is incomplete. ${observed} Full-period zone percentages and per-game rates remain unavailable.`:!known(r.fga)?'Attempt totals are unavailable. Missing coverage is not zero attempts.':r.fga===0?'There are no attempts in this selection. Zero volume is shown, while FG% remains undefined.':low?'Small sample: fewer than 5 attempts. The observed percentage describes these shots; it does not establish a stable shooting tendency.':r.kind==='bin'?'Hexagon area reflects attempts per game. Its color uses made shots divided by all attempts within this bin.':'The same fixed 0–100% color scale and per-game area scale apply to every selected period.'}</div>`;syncSelection();}
function syncSelection(){const displayZone=state.hoverZone||state.zone;document.querySelectorAll('[data-bin]').forEach(el=>{el.classList.toggle('dimmed',state.zone!=='all'&&el.dataset.binZone!==state.zone);el.classList.toggle('active',el.dataset.bin===(state.hoverBin||state.bin));});document.querySelectorAll('[data-court-zone]').forEach(el=>el.classList.toggle('active',el.dataset.courtZone===displayZone));document.querySelectorAll('.zone-button').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.zone===state.zone&&!state.bin)));document.querySelectorAll('[data-row-zone]').forEach(el=>el.classList.toggle('active',el.dataset.rowZone===state.zone));$('all-attempts').setAttribute('aria-pressed',String(state.zone==='all'&&!state.bin));}
function selectZone(id){state.zone=id;state.bin=null;state.hoverZone=null;state.hoverBin=null;renderInspector();announce((id==='all'?'All locations':zoneName(id))+' selected. Shooting detail and zone table updated.');}
function selectBin(id){state.bin=id;state.zone=period().shooting.bins.find(b=>b.id===id)?.zone||'all';state.hoverBin=null;state.hoverZone=null;renderInspector();const b=period().shooting.bins.find(x=>x.id===id);announce(zoneName(b.zone)+' cluster selected: '+b.fgm+' makes in '+b.fga+' attempts, '+percent(b.fg_pct)+', '+number(b.fg_ppg)+' field-goal points per game.');}
function bindChart(){document.querySelectorAll('[data-zone]').forEach(el=>el.addEventListener('click',()=>selectZone(el.dataset.zone)));document.querySelectorAll('[data-court-zone]').forEach(el=>{const id=el.dataset.courtZone;el.addEventListener('pointerenter',()=>{state.hoverZone=id;state.hoverBin=null;renderInspector();});el.addEventListener('pointerleave',()=>{state.hoverZone=null;renderInspector();});el.addEventListener('focus',()=>{state.hoverZone=id;state.hoverBin=null;renderInspector();});el.addEventListener('blur',()=>{state.hoverZone=null;renderInspector();});el.addEventListener('click',()=>selectZone(id));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectZone(id);}if(e.key==='Escape'){selectZone('all');}});});document.querySelectorAll('[data-bin]').forEach(el=>{const id=el.dataset.bin;el.addEventListener('pointerenter',()=>{state.hoverBin=id;state.hoverZone=null;renderInspector();});el.addEventListener('pointerleave',()=>{state.hoverBin=null;renderInspector();});el.addEventListener('focus',()=>{state.hoverBin=id;state.hoverZone=null;renderInspector();});el.addEventListener('blur',()=>{state.hoverBin=null;renderInspector();});el.addEventListener('click',()=>selectBin(id));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectBin(id);}if(e.key==='Escape'){selectZone('all');}});});$('all-attempts').addEventListener('click',()=>selectZone('all'));$('zone-labels').addEventListener('click',()=>{state.labels=!state.labels;$('court-zone-labels')?.toggleAttribute('hidden',!state.labels);$('zone-labels').setAttribute('aria-pressed',String(state.labels));announce(state.labels?'Zone accuracy labels shown.':'Zone accuracy labels hidden.');});$('tracking-unavailable')?.addEventListener('change',e=>{state.missing=e.target.checked;state.bin=null;state.hoverBin=null;state.hoverZone=null;render();$('tracking-unavailable').focus({preventScroll:true});announce(state.missing?'Missing tracking preview. Zone data and plotted dots withheld; box score stays available.':'Returned to actual example tracking coverage.');});}
function contractValue(value){if(value===null||value===undefined||value==='')return '<span class="contract-null">Not recorded</span>';if(Array.isArray(value))return value.map(contractValue).join('<br>');if(typeof value==='object'){const label=value.label??value.text??value.value??'Not recorded',href=safeHref(value.href);return href?`<a href="${esc(href)}">${esc(label)}</a>`:esc(label);}return typeof value==='number'?`<span class="contract-numeric">${esc(value)}</span>`:/^[−+\-]?\$[\d,.]+(?:\s*(?:M|K|million|billion))?$/i.test(String(value))?`<span class="contract-money">${esc(value)}</span>`:esc(value);}
function contractLabel(value){return value===null||value===undefined||value===''?'Not recorded':String(value).replace(/_/g,' ');}
function contractDate(value){if(!value)return 'Date not recorded';const m=/^(\d{4})-(\d{2})-(\d{2})$/.exec(value);return m?new Date(Number(m[1]),Number(m[2])-1,Number(m[3])).toLocaleDateString('en-US',{year:'numeric',month:'short',day:'numeric'}):String(value);}
function contractMetrics(metrics){if(!Array.isArray(metrics)||!metrics.length)return '';return `<div class="contract-metrics">${metrics.map(m=>`<div class="contract-metric"><div class="metric-label">${esc(m.label)}</div><div class="metric-value">${contractValue(m.value)}</div>${m.detail?`<div class="metric-note">${esc(m.detail)}</div>`:''}</div>`).join('')}</div>`;}
function contractSection(section,index){const rows=Array.isArray(section.rows)?section.rows:[],columns=Array.isArray(section.columns)?section.columns:[],items=Array.isArray(section.items)?section.items:[],body=Array.isArray(section.body)?section.body:[section.body];return `<section class="panel contract-section" id="contract-section-${index}" aria-labelledby="contract-section-title-${index}"><header class="panel-head"><div class="contract-section-heading"><span class="contract-section-number" aria-hidden="true">${String(index+1).padStart(2,'0')}</span><div><h3 id="contract-section-title-${index}">${esc(section.title||'Contract detail')}</h3>${section.description?`<p>${esc(section.description)}</p>`:''}</div></div></header>${body.some(Boolean)?`<div class="contract-section-body">${body.filter(Boolean).map(x=>`<p>${contractValue(x)}</p>`).join('')}</div>`:''}${columns.length||rows.length?`<div class="table-scroll"><table class="${columns.length>3?'contract-wide-table':''}" ${columns.length>3?`style="min-width:${Math.max(630,columns.length*125)}px"`:""}>${columns.length?`<thead><tr>${columns.map(c=>`<th scope="col">${esc(typeof c==='object'?c.label:c)}</th>`).join('')}</tr></thead>`:''}<tbody>${rows.length?rows.map(row=>{const values=Array.isArray(row)?row:columns.map(c=>row[typeof c==='object'?c.key:c]);return `<tr>${values.map((v,i)=>i===0?`<th scope="row">${contractValue(v)}</th>`:`<td>${contractValue(v)}</td>`).join('')}</tr>`;}).join(''):`<tr><td colspan="${Math.max(columns.length,1)}"><span class="contract-null">No dated record is available for this section.</span></td></tr>`}</tbody></table></div>`:''}${items.length?`<ul class="contract-items">${items.map(item=>`<li><div>${typeof item==='object'&&item!==null?`${item.label?`<strong>${sourceAnchor(item.href,item.label)}</strong>`:''}${item.value!==undefined?contractValue(item.value):''}${item.description?`<p>${esc(item.description)}</p>`:''}`:esc(item)}</div></li>`).join('')}</ul>`:''}${section.notice?`<div class="contract-notice">${esc(section.notice)}</div>`:''}</section>`;}
function contractSources(record){const all=[...(record?.sources||[]),...(contractPayload().sources||[])],seen=new Set();return all.filter(s=>{const href=safeHref(s.href);if(!href||seen.has(href+'|'+s.label))return false;seen.add(href+'|'+s.label);return true;});}
function contractSidebar(record,sections){const data=contractPayload(),sources=contractSources(record),directory=recordLink('contracts')||recordLink('contract_directory'),facts=record?[['Club',record.team],['Contract type',record.type],['Signed',record.signed_on?contractDate(record.signed_on):null],['Covered seasons',[record.start_season,record.end_season].filter(Boolean).join(' to ')||null],['Record ID',record.id]]:[['Current record',contractLabel(data.status)],['Known through',data.as_of?contractDate(data.as_of):null],['Player record',data.player_id]];return `<aside class="contract-side" aria-label="Contract record navigation and evidence"><section class="panel panel-pad"><div class="eyebrow">Dated contract record</div><h3>${record?'Agreement identity':'Current control status'}</h3><dl class="contract-facts">${facts.map(([label,value])=>`<div><dt>${label}</dt><dd>${contractValue(value)}</dd></div>`).join('')}</dl>${directory?`<a class="contract-directory-link" href="${esc(directory)}">All player contract pages ↗</a>`:''}<button type="button" class="contract-print" id="print-contract">Print complete contract detail</button></section>${sections.length?`<section class="panel panel-pad"><div class="eyebrow">Full detail, always open</div><h3>On this record</h3><nav class="contract-jumps" aria-label="Contract detail sections">${sections.map((s,i)=>`<a href="#contract-section-${i}" data-contract-jump="${i}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title||'Contract detail')}</a>`).join('')}</nav></section>`:''}<section class="panel panel-pad contract-sources-panel"><div class="eyebrow">Evidence and updates</div><h3>Source records</h3>${sources.length?`<div class="contract-source-links">${sources.map(s=>`<a href="${esc(safeHref(s.href))}">${esc(s.label)}</a>`).join('')}</div>`:'<p>No supporting source link has been supplied for this record.</p>'}<p class="contract-document-status">“Not recorded” means the evidence is missing. It does not mean $0, no option, no protection or unrestricted eligibility.</p></section></aside>`;}
function contractRecord(record,{history=false}={}){const data=contractPayload(),sections=record?(Array.isArray(record.sections)?record.sections:[]):(data.sections||[]),summary=record?(record.summary||''):(data.summary||''),status=record?(record.status??'Not recorded'):(data.status??'Not recorded'),title=record?(record.title||'Recorded agreement'):(DATA.contracts?'No current signed contract recorded':'Contract record unavailable');return `<div class="contract-overview"><div><div class="eyebrow">${history?'Historical agreement':record?'Current agreement':'Current contract position'}</div><h3>${esc(title)}</h3>${summary?`<p>${esc(summary)}</p>`:''}</div><div class="contract-status-block"><span class="pill ${record?'':'red'}">${esc(contractLabel(status))}</span><small>Record through ${esc(contractDate(data.as_of))}</small></div></div>${contractMetrics(record?record.metrics:data.metrics)}<div class="contract-layout"><div class="contract-content">${sections.length?sections.map(contractSection).join(''):`<section class="panel contract-section"><div class="panel-head"><h3>Detailed terms are not recorded</h3></div><div class="contract-section-body"><p>No salary schedule, protections, option decision, clause or signed document is supplied in this record. Missing terms have not been filled with assumed values.</p></div></section>`}</div>${contractSidebar(record,sections)}</div>`;}
function contractHistory(){const data=contractPayload(),records=Array.isArray(data.history)?data.history:[];if(!records.length)return `<div class="contract-history-empty"><div class="eyebrow">Contract History</div><h3>No contract history is available in this record.</h3><p>${esc(data.history_notice||'No historical agreement has been supplied for this dated player record. Proposals, cap holds and draft rights are not substituted for signed contracts.')}</p></div><div class="contract-layout"><div class="contract-content">${(data.sections||[]).map(contractSection).join('')}</div>${contractSidebar(null,data.sections||[])}</div>`;let selected=records.find(r=>r.id===state.contractId)||records[0];state.contractId=selected.id;return `<div class="contract-history-list" aria-label="Select a historical contract">${records.map(record=>`<button type="button" class="contract-history-card" data-contract-id="${esc(record.id)}" aria-pressed="${record.id===selected.id}" aria-controls="contract-history-detail"><span class="contract-history-top"><span><strong class="contract-history-title">${esc(record.title||record.team||'Contract record')}</strong><span class="contract-history-kind">${esc([record.team,record.type].filter(Boolean).join(' · '))}</span></span><span class="pill">${esc(contractLabel(record.status))}</span></span><span class="contract-history-info">${esc([record.start_season&&record.end_season?record.start_season+' to '+record.end_season:record.start_season||record.end_season,record.signed_on?'Signed '+contractDate(record.signed_on):'Signing date not recorded'].filter(Boolean).join(' · '))}</span><span class="contract-history-open">${record.id===selected.id?'Viewing complete terms below':'Open complete terms'} ↘</span></button>`).join('')}</div><div class="contract-record-label">Selected agreement · Full terms and source record</div><div id="contract-history-detail" tabindex="-1">${contractRecord(selected,{history:true})}</div>`;}
function contractView(){const data=contractPayload(),history=Array.isArray(data.history)?data.history:[],isHistory=state.contractTab==='history';return `<div class="contract-view"><div class="view-head"><div><h2 id="view-title" tabindex="-1">Contract</h2><p>Current terms and the complete recorded agreement history.<br>Salary, cap treatment, protection and player control stay separate.</p></div><span class="pill ${LIVE?'':'red'}">${LIVE?'Dated player record':'Illustrative contract view'}</span></div><nav class="contract-subnav" role="tablist" aria-label="Contract record views"><button type="button" class="contract-subtab" id="contract-tab-current" data-contract-tab="current" role="tab" aria-selected="${!isHistory}" aria-controls="contract-pane" tabindex="${isHistory?-1:0}">Current Contract</button><button type="button" class="contract-subtab" id="contract-tab-history" data-contract-tab="history" role="tab" aria-selected="${isHistory}" aria-controls="contract-pane" tabindex="${isHistory?0:-1}">Contract History <span class="contract-count">${history.length}</span></button><span class="contract-subnav-note">All sections expanded · ${esc(contractDate(data.as_of))}</span></nav><section id="contract-pane" role="tabpanel" aria-labelledby="contract-tab-${state.contractTab}" tabindex="0">${isHistory?contractHistory():contractRecord(data.current||null)}</section></div>`;}
function updateContractURL(){const query=new URLSearchParams(location.search);if(state.contractTab==='history'&&state.contractId)query.set('contract',state.contractId);else query.delete('contract');history.replaceState(null,'',location.pathname+(query.toString()?'?'+query.toString():'')+(state.contractTab==='history'?'#contract-history':'#contract'));}
function bindContracts(){const tabs=[...document.querySelectorAll('[data-contract-tab]')];tabs.forEach((button,index)=>{button.addEventListener('click',()=>{state.contractTab=button.dataset.contractTab;render();updateContractURL();$('contract-tab-'+state.contractTab).focus({preventScroll:true});announce((state.contractTab==='history'?'Contract History':'Current Contract')+' opened with complete recorded details.');});button.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const next=event.key==='Home'?0:event.key==='End'?tabs.length-1:(index+(event.key==='ArrowLeft'?-1:1)+tabs.length)%tabs.length;state.contractTab=tabs[next].dataset.contractTab;render();updateContractURL();$('contract-tab-'+state.contractTab).focus();});});document.querySelectorAll('[data-contract-id]').forEach(button=>button.addEventListener('click',()=>{state.contractId=button.dataset.contractId;render();updateContractURL();$('contract-history-detail').focus({preventScroll:true});$('contract-history-detail').scrollIntoView({block:'start',behavior:'auto'});announce('Historical contract selected. Every recorded term and source is displayed.');}));document.querySelectorAll('[data-contract-jump]').forEach(link=>link.addEventListener('click',event=>{event.preventDefault();const section=$('contract-section-'+link.dataset.contractJump);section.scrollIntoView({block:'start',behavior:'auto'});section.setAttribute('tabindex','-1');section.focus({preventScroll:true});}));$('print-contract')?.addEventListener('click',()=>window.print());}

function awardsScenario(){return DATA.awards.scenarios.find(s=>s.id===state.awardScenario)||DATA.awards.scenarios[0];}
function earnedAnnualAwards(s){return s.records.filter(r=>r.scope==='annual'&&r.status==='earned'&&r.season===s.season&&typeof r.awarded_on==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.awarded_on)&&r.awarded_on<=s.cutoff);}
function awardsView(){const s=awardsScenario(),earned=earnedAnnualAwards(s),independent=!LIVE&&s.id!=='current',stats=recordLink('stats');return `<div class="view-head"><div><h2 id="view-title" tabindex="-1">Season awards</h2><p>Annual awards earned in the selected season. Confirmed recognition only.</p></div><span class="pill ${independent?'red':'gold'}">${independent?'Independent design scenario':'Earned annual awards'}</span></div><section class="awards-headline"><div><div class="eyebrow">${esc(s.season)} · Season recognition</div><h2>${earned.length?earned.length+' earned annual awards':'No annual awards earned yet.'}</h2><p>${esc(s.notice||'')}${!independent?' Weekly and monthly recognitions remain in the statistical reports; they do not become annual award banners.':''}</p></div><div class="award-mark" aria-hidden="true">${icons.trophy}</div></section><div class="awards-controls"><label for="award-scenario">${LIVE?'SEASON':'SEASON / EXAMPLE'}<select id="award-scenario">${DATA.awards.scenarios.map(x=>`<option value="${esc(x.id)}" ${x.id===s.id?'selected':''}>${esc(x.label||x.season)}</option>`).join('')}</select></label><p class="metric-note">Confirmed through ${esc(s.cutoff)}.<br>Nominations and pending outcomes are excluded.</p></div><section class="award-grid" aria-label="Annual award banners">${earned.length?earned.map((a,i)=>`<article class="award-banner"><div class="season">${esc(a.season)}</div><div class="award-name">${esc(a.name)}</div><div class="award-seal" aria-hidden="true">${i%2?icons.star:icons.trophy}</div><p style="margin-top:14px">${esc(a.description||(LIVE?'Confirmed annual recognition.':'Earned recognition in this illustrative season.'))}</p><div class="award-date">CONFIRMED ${esc(a.awarded_on)}</div></article>`).join(''):`<div class="award-empty"><div class="empty-year">${esc(s.season)}</div><h3>There is no earned annual banner to display.</h3><p>${LIVE?'No earned annual award is recorded for this season through the selected cutoff. Weekly and monthly honors remain in their own period records.':'The season remains open in this sample. No future selection, trophy or career honor is inferred from performance or copied from the reference image.'}</p></div>`}</section><div class="award-context"><section class="panel"><div class="panel-head"><div><h3>Award record</h3><p>Season, confirmation date and supporting ${LIVE?'career':'example'} record</p></div></div><div class="table-scroll"><table id="annual-awards-table"><thead><tr><th>Award</th><th>Season</th><th>Confirmed</th><th>Source</th></tr></thead><tbody>${earned.length?earned.map(a=>`<tr><th scope="row">${esc(a.name)}</th><td>${esc(a.season)}</td><td>${esc(a.awarded_on)}</td><td>${sourceAnchor(a.source_href,a.source_label||(LIVE?'Career decision record':'Independent example record'))}</td></tr>`).join(''):'<tr><td colspan="4">No earned annual records meet this season and cutoff.</td></tr>'}</tbody></table></div></section><section class="panel panel-pad"><h3 class="support-title">What belongs on a season banner</h3><p class="insight" style="margin-top:0">An earned annual award, its season and its actual confirmation date. The selected season’s cutoff controls what can be shown. A weekly award, a monthly award, a nomination and an unannounced result each remain separate.</p><p class="insight">${LIVE?'Every displayed honor belongs to this career and the selected season. A missing annual award record remains empty.':independent?'This design scenario is separate from the six-game 2003 example. It does not add a future result to the player’s career.':'The November 2003 sample has short-period recognitions but no earned annual award. An empty annual section is the accurate result.'}</p>${stats?`<a id="awards-stats-link" class="text-button" style="display:inline-block;margin-top:12px;padding-left:0" href="${esc(stats)}">Open period-by-period statistical reports ↗</a>`:''}</section></div>`;}
function bindAwards(){$('award-scenario').addEventListener('change',e=>{state.awardScenario=e.target.value;render();$('award-scenario').focus({preventScroll:true});announce('Annual award '+(LIVE?'season':'scenario')+' changed. Only earned records in the selected season and cutoff are shown.');});}
function changePeriod(id){state.period=id;const query=new URLSearchParams(location.search);query.set('period',id);history.replaceState(null,'',location.pathname+'?'+query.toString()+'#'+state.tab);state.zone='all';state.bin=null;state.hoverBin=null;state.hoverZone=null;render();announce(period().label+' selected. Totals, percentages, dot frequencies and source games updated using the same fixed scales.');}
function changeTab(tab){if(!enabledTabs.includes(tab))return;state.tab=tab;state.hoverZone=null;state.hoverBin=null;render();if(tab==='contract')updateContractURL();else history.replaceState(null,'',location.pathname+location.search+'#'+tab);}
$('scope-select').addEventListener('change',e=>{const current=period(),p=PERIODS.find(p=>p.kind===e.target.value&&p.competition===current?.competition)||PERIODS.find(p=>p.kind===e.target.value);if(p)changePeriod(p.id);$('scope-select').focus({preventScroll:true});});$('period-select').addEventListener('change',e=>{changePeriod(e.target.value);$('period-select').focus({preventScroll:true});});[...document.querySelectorAll('[data-tab]')].filter(b=>enabledTabs.includes(b.dataset.tab)).forEach((b,i,all)=>{b.addEventListener('click',()=>changeTab(b.dataset.tab));b.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const next=e.key==='Home'?0:e.key==='End'?all.length-1:(i+(e.key==='ArrowLeft'?-1:1)+all.length)%all.length;changeTab(all[next].dataset.tab);all[next].focus();});});window.addEventListener('hashchange',()=>{const tab=contractHashTab(location.hash);if(!tab||!enabledTabs.includes(tab))return;state.tab=tab;if(tab==='contract'){state.contractTab=location.hash==='#contract-history'?'history':'current';state.contractId=new URLSearchParams(location.search).get('contract');}render();});
initializeLinks();
render();
